# 1
U(1,('Understanding the arts','ጥበባትን መረዳት'),
 [match(('Elements of visual art','የዕይታዊ ጥበብ አላባውያን'),('Elements are the building blocks of a picture; principles are how we arrange them.','አላባውያን የሥዕል መሠረቶች ናቸው፤ መርሖች እንዴት እንደምናደራጃቸው ያሳያሉ።'),[[(('Line','መስመር'),('a mark between two points','በሁለት ነጥቦች መካከል ያለ ምልክት')),(('Shape','ቅርጽ'),('a flat, two-dimensional area','ጠፍጣፋ ባለ ሁለት ልኬት ቦታ')),(('Form','ይዘት/ቅርጸ አካል'),('a three-dimensional object','ባለ ሦስት ልኬት ነገር')),(('Texture','ልስላሴ/ሸካራነት'),('how a surface feels or looks','ገጽ እንዴት እንደሚሰማ ወይም እንደሚታይ'))],[(('Value','ብርሃንና ጥላ'),('lightness or darkness of a colour','የቀለም ብሩህነት ወይም ጨለማነት')),(('Space','ቦታ/ክፍተት'),('area around and between objects','በነገሮች ዙሪያና መካከል ያለ ቦታ')),(('Colour','ቀለም'),('hue, made from primary colours','ከመሠረታዊ ቀለማት የሚሠራ'))]]),
  quiz(('Principles, music and drama','መርሖች፣ ሙዚቃና ተውኔት'),('Design principles: balance, contrast, emphasis, rhythm, unity, proportion. Ethiopian music uses four main kignit (modes): tizita, bati, ambassel and anchihoye. Film and theatre go through pre-production, production and post-production.','የንድፍ መርሖች፦ ሚዛን፣ ንፅፅር፣ ትኩረት፣ ምት፣ አንድነት፣ መጠን። የኢትዮጵያ ሙዚቃ አራት ዋና ቅኝቶችን ይጠቀማል፦ ትዝታ፣ ባቲ፣ አምባሰልና አንቺሆዬ። ፊልምና ቲያትር ቅድመ ዝግጅት፣ ዝግጅትና ድኅረ ዝግጅት ያልፋሉ።'),[
   q('The four main Ethiopian kignit are tizita, bati, ambassel and…','አራቱ ዋና የኢትዮጵያ ቅኝቶች ትዝታ፣ ባቲ፣ አምባሰልና…',[('anchihoye','አንቺሆዬ'),('reggae','ሬጌ')]),
   q('Placing a bright red spot in a grey picture creates…','በግራጫ ሥዕል ውስጥ ደማቅ ቀይ ነጥብ ማድረግ የሚፈጥረው…',[('emphasis/contrast','ትኩረት/ንፅፅር'),('silence','ጸጥታ')]),
   q('Which is an Ethiopian string instrument?','የኢትዮጵያ ባለ ክር መሣሪያ?',[('masinqo','ማሲንቆ'),('kebero','ከበሮ'),('washint','ዋሽንት')]),
   q('Writing the script happens in…','ጽሑፉን መጻፍ የሚከናወነው በ…',[('pre-production','ቅድመ ዝግጅት'),('post-production','ድኅረ ዝግጅት')]),
   q('Eskista is a dance mainly of the…','እስክስታ በዋናነት የ… ውዝዋዜ ነው',[('shoulders','ትከሻ'),('feet only','እግር ብቻ')])])],
 [q('A three-dimensional object is a…','ባለ ሦስት ልኬት ነገር…',[('form','ቅርጸ አካል'),('line','መስመር')]),q('The kebero is a…','ከበሮ…',[('drum','የምት መሣሪያ'),('flute','የትንፋሽ መሣሪያ')]),q('Editing a film is…','ፊልምን ማረም…',[('post-production','ድኅረ ዝግጅት'),('pre-production','ቅድመ ዝግጅት')]),q('Balance in design means…','በንድፍ ሚዛን ማለት…',[('visual weight is evenly spread','የዕይታ ክብደት በእኩል መሰራጨቱ'),('using one colour','አንድ ቀለም መጠቀም')])],
 notes(('Art uses elements (line, shape, form, colour, texture, value, space) arranged by principles; Ethiopian music has four kignit, and film and theatre are produced in stages.','ጥበብ በመርሖች የሚደራጁ አላባውያንን (መስመር፣ ቅርጽ፣ ቅርጸ አካል፣ ቀለም፣ ሸካራነት፣ ብርሃንና ጥላ፣ ቦታ) ይጠቀማል፤ የኢትዮጵያ ሙዚቃ አራት ቅኝቶች አሉት፤ ፊልምና ቲያትር በደረጃ ይዘጋጃሉ።'),
  [('Seven elements of visual art.','ሰባቱ የዕይታዊ ጥበብ አላባውያን።'),('Design principles: balance, contrast, rhythm, unity.','የንድፍ መርሖች፦ ሚዛን፣ ንፅፅር፣ ምት፣ አንድነት።'),('Ethiopian music: instruments and four kignit; folk dance.','የኢትዮጵያ ሙዚቃ፦ መሣሪያዎችና አራት ቅኝቶች፤ የሕዝብ ውዝዋዜ።'),('Film/theatre: pre-production, production, post-production.','ፊልም/ቲያትር፦ ቅድመ ዝግጅት፣ ዝግጅት፣ ድኅረ ዝግጅት።')],
  [('አላባ','element','የጥበብ መሠረት'),('ቅኝት','mode (kignit)','የሙዚቃ ቃና ሥርዓት'),('ንፅፅር','contrast','ልዩነትን ማጉላት')],('Tizita, Bati, Ambassel, Anchihoye.','ትዝታ፣ ባቲ፣ አምባሰል፣ አንቺሆዬ።'),
  [(('Name four elements of art','አራት የጥበብ አላባውያንን ጥቀሱ'),('line, shape, colour, texture','መስመር፣ ቅርጽ፣ ቀለም፣ ሸካራነት')),(('Name the four kignit','አራቱን ቅኝቶች ጥቀሱ'),('tizita, bati, ambassel, anchihoye','ትዝታ፣ ባቲ፣ አምባሰል፣ አንቺሆዬ'))],
  (('Kignit listening cards','የቅኝት ማዳመጫ ካርዶች'),('Make cards with QR links to one example song for each kignit, chosen with your music teacher.','ከሙዚቃ መምህራችሁ ጋር ለእያንዳንዱ ቅኝት አንድ ምሳሌ ዘፈን የሚያገናኝ QR ያለባቸው ካርዶች ሥሩ።'),[('Pick one legal example for each kignit.','ለእያንዳንዱ ቅኝት አንድ ሕጋዊ ምሳሌ ምረጡ።'),('Write how it feels (sad, joyful…).','ምን ስሜት እንደሚሰጥ ጻፉ (ኃዘን፣ ደስታ…)።'),('Design and print the cards.','ካርዶቹን ንደፉና አትሙ።'),('Play a "guess the kignit" game.','"ቅኝቱን ገምቱ" ጨዋታ ተጫወቱ።')])),
 sm(('The language of art','የጥበብ ቋንቋ'),[('Elements','አላባውያን'),('Principles','መርሖች'),('Music and dance','ሙዚቃና ውዝዋዜ'),('Film and theatre','ፊልምና ቲያትር')]),
 ('elements and principles of art, Ethiopian music, instruments, kignit and dance, and film and theatre production','የጥበብ አላባውያንና መርሖች፣ የኢትዮጵያ ሙዚቃ፣ መሣሪያዎች፣ ቅኝትና ውዝዋዜ፣ የፊልምና የቲያትር ዝግጅት'))

