U(3,('Culture and history','ባህልና ታሪክ'),
 [match(('Monuments of Ethiopia','የኢትዮጵያ ሐውልቶች'),('Ethiopia has some of Africa’s oldest monuments.','ኢትዮጵያ ከአፍሪካ ጥንታዊ ሐውልቶች አንዳንዶቹ አሏት።'),[[(('Axum','አክሱም'),('tall carved stone obelisks (stelae)','ረጃጅም የተቀረጹ የድንጋይ ሐውልቶች')),(('Tiya','ጥያ'),('carved standing stones south of Addis Ababa','ከአዲስ አበባ በስተደቡብ የተቀረጹ ቋሚ ድንጋዮች')),(('Konso','ኮንሶ'),('wooden waga statues and stone terraces','የእንጨት ዋካ ሐውልቶችና የድንጋይ እርከኖች'))],[(('Lalibela','ላሊበላ'),('churches carved from solid rock','ከአንድ ወጥ ዓለት የተፈለፈሉ አብያተ ክርስቲያናት')),(('Fasil Ghebbi','ፋሲል ግቢ'),('17th-century castles in Gondar','በጎንደር የ17ኛው ክፍለ ዘመን ቤተ መንግሥቶች')),(('Harar Jugol','ሐረር ጀጎል'),('walled historic city with many mosques','ብዙ መስጊዶች ያሉት በግንብ የታጠረ ጥንታዊ ከተማ'))]]),
  quiz(('Music, dance and crafts in history','ሙዚቃ፣ ውዝዋዜና የእጅ ጥበብ በታሪክ'),('Ethiopian instruments are grouped as string (masinqo, krar, begena), wind (washint, embilta) and percussion (kebero, negarit). Traditional crafts include weaving, pottery, basketry and leatherwork.','የኢትዮጵያ መሣሪያዎች ባለ ክር (ማሲንቆ፣ ክራር፣ በገና)፣ የትንፋሽ (ዋሽንት፣ እምቢልታ) እና የምት (ከበሮ፣ ነጋሪት) ተብለው ይመደባሉ። ባህላዊ የእጅ ጥበቦች ሽመናን፣ ሸክላን፣ ቅርጫትንና የቆዳ ሥራን ያካትታሉ።'),[
   q('The begena is a…','በገና…',[('string instrument','ባለ ክር መሣሪያ'),('drum','ከበሮ')]),
   q('The washint is played by…','ዋሽንት የሚጫወተው በ…',[('blowing','በመንፋት'),('hitting','በመምታት')]),
   q('The negarit is a large…','ነጋሪት ትልቅ…',[('drum used for announcements','ለአዋጅ የሚውል ከበሮ'),('flute','ዋሽንት')]),
   q('Making baskets from grass is…','ከሣር ቅርጫት መሥራት…',[('basketry','የሰፌድና ቅርጫት ሥራ'),('pottery','ሸክላ ሥራ')])])],
 [q('The stelae of Axum are made of…','የአክሱም ሐውልቶች የተሠሩት ከ…',[('stone','ድንጋይ'),('wood','እንጨት')]),q('Konso waga statues are made of…','የኮንሶ ዋካ ሐውልቶች የተሠሩት ከ…',[('wood','እንጨት'),('gold','ወርቅ')]),q('The krar is a … instrument.','ክራር … መሣሪያ ነው',[('string','ባለ ክር'),('percussion','የምት')]),q('Fasil Ghebbi is in…','ፋሲል ግቢ የሚገኘው በ…',[('Gondar','ጎንደር'),('Harar','ሐረር')])],
 notes(('Ethiopian culture lives in its monuments (Axum, Tiya, Konso, Lalibela, Gondar, Harar), its instruments, dances and traditional crafts.','የኢትዮጵያ ባህል በሐውልቶቿ (አክሱም፣ ጥያ፣ ኮንሶ፣ ላሊበላ፣ ጎንደር፣ ሐረር)፣ በመሣሪያዎቿ፣ በውዝዋዜዎቿና በባህላዊ የእጅ ጥበቦቿ ውስጥ ይኖራል።'),
  [('History of Ethiopian music and dance.','የኢትዮጵያ ሙዚቃና ውዝዋዜ ታሪክ።'),('Instruments: string, wind, percussion.','መሣሪያዎች፦ ባለ ክር፣ የትንፋሽ፣ የምት።'),('Monuments: Axum, Tiya, Konso, Lalibela.','ሐውልቶች፦ አክሱም፣ ጥያ፣ ኮንሶ፣ ላሊበላ።'),('Crafts: weaving, pottery, basketry, leather.','የእጅ ጥበብ፦ ሽመና፣ ሸክላ፣ ቅርጫት፣ ቆዳ።')],
  [('ሐውልት','monument','የመታሰቢያ ሥራ'),('የእጅ ጥበብ','craft','በእጅ የሚሠራ ጥበብ'),('ነጋሪት','negarit','ትልቅ ከበሮ')],('String, wind, percussion — masinqo, washint, kebero.','ባለ ክር፣ ትንፋሽ፣ ምት — ማሲንቆ፣ ዋሽንት፣ ከበሮ።'),
  [(('Classify: krar, embilta, kebero','መድቡ፦ ክራር፣ እምቢልታ፣ ከበሮ'),('string, wind, percussion','ባለ ክር፣ ትንፋሽ፣ ምት')),(('Three UNESCO heritage sites in Ethiopia','በኢትዮጵያ ሦስት የዩኔስኮ ቅርሶች'),('Axum, Lalibela, Tiya','አክሱም፣ ላሊበላ፣ ጥያ'))],
  (('Mini-museum corner','የትንሽ ሙዚየም ጥግ'),('Collect and label everyday crafts from families to show local culture.','የአካባቢ ባህልን ለማሳየት ከቤተሰቦች የዕለት የእጅ ጥበብ ዕቃዎችን ሰብስቡና መለያ ስጡ።'),[('Borrow 10 crafts with owners’ permission.','በባለቤቶቹ ፈቃድ 10 የእጅ ጥበብ ዕቃዎችን ተዋሱ።'),('Write a bilingual label for each.','ለእያንዳንዱ ባለሁለት ቋንቋ መለያ ጻፉ።'),('Arrange them by material.','በቁሳቁስ አደራጁ።'),('Invite parents for a visit.','ወላጆችን ለጉብኝት ጋብዙ።')])),
 sm(('Art through the ages','ጥበብ በዘመናት'),[('Music and dance history','የሙዚቃና ውዝዋዜ ታሪክ'),('Instruments','መሣሪያዎች'),('Monuments','ሐውልቶች'),('Crafts','የእጅ ጥበቦች')]),
 ('the culture and history of music, instruments, dance, monuments and crafts','የሙዚቃ፣ የመሣሪያ፣ የውዝዋዜ፣ የሐውልትና የእጅ ጥበብ ባህልና ታሪክ'))

